/// <summary>
/// Initializes the form. Initializes various form members variables.
/// </summary>
void init()
{
    boolean isRetailSpecialGroup = false;

    next init();

    // Vendor account only visible and editable for Supplemental retail hierarchy
    if (EcoResCategoryHierarchyRole::findRoleHierarchyPair(EcoResCategoryNamedHierarchyRole::RetailSpecialGroup, currentSelectedCategoryHierarchy.recId))
    {
        isRetailSpecialGroup = true;
    }

    EcoResCategory_ds.object(fieldNum(EcoResCategory, METVendAccount)).visible(isRetailSpecialGroup);
    EcoResCategory_ds.object(fieldNum(EcoResCategory, METVendAccount)).allowEdit(isRetailSpecialGroup);
}
